import React from 'react';
import upArrow from "../../img/up-arrow.svg"

const ToTop = () => {
    return (
        <aside className="toTop">
            <div className="toTop-container">
                <img src={upArrow} alt="Up arrow"/>
            </div>
        </aside>
)
    ;
};

export default ToTop;
